targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		pageID: 'mid-installation-plan',
		requiredParams: {
			"authType" : api.context.props.authType,
			"installMethod": api.context.props.installMethod,
			"midServerOS": api.context.props.midServerOS
		},
		optionalParams: {
			"midServerName": api.state.midName,
			"midServerPurpose": api.state.midPurpose,
			"midServerUser": api.state.midUserLookup,
			"midServerProxyHost": api.state.proxyHostInput,
			"midServerProxyPort": api.state.proxyPortInput,
			"midServerServiceName": api.state.serviceNameInput,
		}
	};
})

